
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_2d_b88_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_2d_b88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.489496479855899e-01, -8.490257672622329e-01, -8.491481220678682e-01, -8.493436201239162e-01, -8.496530852397488e-01, -8.501359579508494e-01, -8.508726987591185e-01, -8.519555629918644e-01, -8.534341098022857e-01, -8.550940722056326e-01, -8.556935433364450e-01, -8.508358297133702e-01, -8.287722069383848e-01, -7.667178309944137e-01, -6.396680532248732e-01, -4.520309783662175e-01, -2.603777877340087e-01, -1.414007831620276e-01, -1.013572915960910e-01, -8.528068216219867e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


